package dev.atqiya.ledgerly.reporting.api;
import dev.atqiya.ledgerly.identity.application.AuthenticatedUser; import dev.atqiya.ledgerly.ledger.domain.TransactionType; import dev.atqiya.ledgerly.reporting.application.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.LocalDate; import java.util.*; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/workspaces/{workspaceId}") public class ReportingController{
 private final FinancialReportService reports;private final CategorizationService categorization;public ReportingController(FinancialReportService r,CategorizationService c){reports=r;categorization=c;}
 @GetMapping("/reports/financial-summary") public FinancialReportService.FinancialReport report(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID workspaceId,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to){return reports.report(u.id(),workspaceId,from,to);}
 @PostMapping("/categorization-rules") public CategorizationService.RuleView create(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID workspaceId,@Valid @RequestBody CreateRule r){return categorization.create(u.id(),workspaceId,r.name(),r.categoryId(),r.type(),r.descriptionContains(),r.priority());}
 @GetMapping("/categorization-rules") public List<CategorizationService.RuleView> rules(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID workspaceId){return categorization.list(u.id(),workspaceId);}
 @PostMapping("/categorization-rules/apply") public Map<String,Integer> apply(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID workspaceId){return Map.of("categorizedTransactions",categorization.apply(u.id(),workspaceId));}
 @PostMapping("/categorization-rules/{ruleId}/disable") public void disable(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID workspaceId,@PathVariable UUID ruleId){categorization.disable(u.id(),workspaceId,ruleId);}
 public record CreateRule(@NotBlank @Size(max=120) String name,@NotNull UUID categoryId,@NotNull TransactionType type,@NotBlank @Size(max=120) String descriptionContains,@Min(1) @Max(1000) int priority){}
}
